{
  "description": "Adds a /pomodoro focus timer with a toast when it ends",
  "modules": [
    "./register.js"
  ]
}

// /pomodoro [minutes] starts a timer; a toast appears when it ends.
let timer = null

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'pomodoro', description: 'Start a focus timer', argumentHint: '[minutes]', immediate: true })
    return next(e)
  })
  on('command.run', { command: 'pomodoro' }, async ($, e) => {
    const minutes = Number(e.args) > 0 ? Number(e.args) : 25
    if (timer) timer.cancel()
    timer = $.clock.after(minutes * 60 * 1000, () => {
      $.ui.toast('Time for a break. ' + minutes + ' minutes are up.')
    })
    return { text: 'Focus timer started for ' + minutes + ' minutes' }
  })
}

