// Updates a one-line status under the prompt every minute.
export function register(on) {
  on('session.start', async ($, e, next) => {
    let minutes = 0
    $.ui.status('session open: 0 min')
    $.clock.every(60_000, () => {
      minutes += 1
      $.ui.status('session open: ' + minutes + ' min')
    })
    return next(e)
  })
}

