{
  "description": "Adds /note to append lines to notes.md",
  "modules": [
    "./register.js"
  ]
}

// /note some text -> appends a bullet to notes.md in the working directory.
export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'note', description: 'Append a line to notes.md', argumentHint: '[text]', immediate: true })
    return next(e)
  })
  on('command.run', { command: 'note' }, async ($, e) => {
    if (!e.args) return { text: 'Usage: /note your text' }
    let existing = ''
    if (await $.fs.exists('notes.md')) existing = await $.fs.read('notes.md')
    await $.fs.write('notes.md', existing + '- ' + e.args + '\n')
    return { text: 'Saved to notes.md' }
  })
}

