{
  "description": "Opens a pane with an editable Markdown cheat sheet",
  "modules": [
    "./register.js"
  ]
}

// /cheatsheet opens a pane that draws Markdown. Edit the text below.
const sheet = '## Git basics\n\n- `git status` shows changes\n- `git add .` stages files\n- `git commit -m "msg"` saves a snapshot\n\n> Press Escape to close this pane'

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'cheatsheet', description: 'Open the cheat sheet pane' })
    return next(e)
  })
  on('command.run', { command: 'cheatsheet' }, async ($) => {
    await $.ui.open({ id: 'cheatsheet', focus: true, closeOnEscape: true })
    return {}
  })
  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== 'cheatsheet') return next(e)
    const { Markdown } = $.ui.resolve(e)
    return Markdown({ text: sheet })
  })
}

